#[test]fn every_identity_field_mutation_has_full_prefix_parity(){use wire::Value::*;let(c,a,m,p)=expected();let mut cases=vec![(vec!["snapshot_index"],U64(1)),(vec!["identity","pattern"],U64(p as u64+1)),(vec!["identity","map_bytes"],Bytes(vec![0])),(vec!["identity","map_published"],Bool(false)),(vec!["identity","publication_attempted"],Bool(false))];for k in ["public_sha256","factor_sha256","launch_sha256","binding_sha256"]{cases.push((vec!["identity",k],Bytes(vec![0x99;32])))}for k in ["event_count","byte_end"]{cases.push((vec!["identity","map_ack",k],U64(u64::MAX)))}for k in ["binding_sha256","last_event_sha256"]{cases.push((vec!["identity","map_ack",k],Text("a".repeat(64))))}for(path,v)in cases{let mut root=decode(raw()).value.unwrap();set(&mut root,&path,v);let mut b=b"OWNSEARCH\x01".to_vec();encode(&root,&mut b);let t=prefix(b[..4096].to_vec());assert_eq!(t.result(),Ok(wire::strict_prefix::State::IncompleteIdentityAvailable),"{path:?}");let full=check_identity_binding(&root,0,&c,&a,&m,p);let partial=check_prefix_binding(&t,0,&c,&a,&m,p);assert!(full.is_err(),"{path:?}");assert_eq!(full,partial,"{path:?}");}}
